from pathlib import Path
import json, hashlib, urllib.parse
p=Path(__file__).resolve().parent
prefix='data/municipal/durham/'
def h(n):return hashlib.sha256((p/n).read_bytes()).hexdigest()
def query(base):return base+'/query?'+urllib.parse.urlencode({'where':'1=1','outFields':'*','returnGeometry':'true','outSR':4326,'f':'geojson'})
