 return {'id':id,'municipality':city,'municipalityName':city,'municipalityCode':code,'regionCode':'3518','region':'Durham','path':prefix+file,'nameField':namefield,'idField':idfield,'geographyType':'neighbourhood','publisher':publisher,'sourceUrl':url,'downloadUrl':download,'license':license,'retrievedDate':'2026-11-06','sha256':h(file),'featureCount':len(json.loads((p/file).read_text())['features']),**extra}
