files={f.name:{'sha256':h(f.name),'bytes':f.stat().st_size} for f in p.iterdir() if f.is_file() and f.suffix not in ['.py'] and f.name!='sources.json' and f.name not in ['health-profile-indicators.json','health-profiles-2021-raw.json']}
manifest={'schemaVersion':1,'retrievedDate':'2026-11-06','sources':sources,'coverageResearch':research,'statisticsNotes':['Health 2021 source has only median AFTER-TAX household income, so atlas before-tax income is null.','Health source publishes only the total visible-minority category, not its 13 component categories. Do not substitute ethnic-origin percentages from Pickering profiles.','Health children statistic is directly published percentage / 100. Total population is the directly published numerator of population density. No area weighting or median aggregation is performed.'],'supplementaryCandidates':[{'path':prefix+'durham-planning-hamlets.geojson','sourceUrl':'https://maps.durham.ca/arcgis/rest/services/Open_Data/OfficialPlanConsolidation2024_Map1/MapServer/15','nameField':'NAME','municipalityField':'Munic','license':health_license,'includeByDefault':False,'reason':'Partial planning settlement coverage; not used to cut complete health-profile geometries.'}],'files':files}
(p/'sources.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
print([(s['municipality'],s['featureCount'],s['path']) for s in sources])
